def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    """
    Perform string transformation from A to B using a set of transformation rules.
    Uses BFS up to 10 steps to find the minimal number of transformations.
    Returns the minimal step count or "NO ANSWER!" if impossible.
    """
    # Basic input validation
    if not isinstance(A, str) or not isinstance(B, str) or not isinstance(rules, list):
        raise TypeError("A and B must be strings; rules must be a list of tuples.")
    for r in rules:
        if not isinstance(r, tuple) or len(r) != 2:
            raise TypeError("Each rule must be a tuple of two strings.")
        if not isinstance(r[0], str) or not isinstance(r[1], str):
            raise TypeError("Rule elements must be strings.")
    # Edge case: already equal
    if A == B:
        return 0
    max_depth = 10
    from collections import deque
    queue = deque()
    queue.append((A, 0))
    visited = {A}
    while queue:
        current, depth = queue.popleft()
        if depth >= max_depth:
            continue
        for src, tgt in rules:
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + tgt + current[idx + len(src):]
                if new_str == B:
                    return depth + 1
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, depth + 1))
                start = idx + 1  # allow overlapping matches
    return "NO ANSWER!"

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    # Basic type validation
    if not isinstance(scenario, str):
        raise TypeError("scenario must be a string")
    if not isinstance(liar_count, set) or not all(isinstance(n, str) for n in liar_count):
        raise TypeError("liar_count must be a set of strings")
    if not isinstance(statements, dict):
        raise TypeError("statements must be a dictionary")
    if not isinstance(days_of_week, set) or not all(isinstance(d, str) for d in days_of_week):
        raise TypeError("days_of_week must be a set of strings")

    def statement_truth(speaker: str, stmt: str) -> bool:
        """
        Determine the truth value of a statement about guilt.

        Returns True if the statement is true under the given scenario,
        False if it is false, and True for unparseable statements
        (they are ignored in consistency checks).
        """
        # Ignore statements that mention a day of the week
        if any(day in stmt for day in days_of_week):
            return True  # treated as neutral

        # Normalize statement: strip whitespace and trailing period
        s = stmt.strip().rstrip('.')
        parts = s.split()

        # Handle "I am guilty." / "I am not guilty."
        if len(parts) == 3 and parts[0] == 'I' and parts[1] == 'am':
            if parts[2] == 'guilty':
                return scenario == speaker
        if len(parts) == 4 and parts[0] == 'I' and parts[1] == 'am' and parts[2] == 'not' and parts[3] == 'guilty':
            return scenario != speaker

        # Handle "<NAME> is guilty." / "<NAME> is not guilty."
        if len(parts) == 3 and parts[1] == 'is':
            name = parts[0]
            if parts[2] == 'guilty':
                return scenario == name
        if len(parts) == 4 and parts[1] == 'is' and parts[2] == 'not' and parts[3] == 'guilty':
            name = parts[0]
            return scenario != name

        # Unparseable statements are considered neutral (do not affect consistency)
        return True

    for speaker, stmts in statements.items():
        if not isinstance(speaker, str):
            raise TypeError("Participant names must be strings")
        if not isinstance(stmts, list):
            raise TypeError("Statements for each participant must be a list")
        is_liar = speaker in liar_count
        for stmt in stmts:
            if not isinstance(stmt, str):
                raise TypeError("Each statement must be a string")
            truth = statement_truth(speaker, stmt)
            # If the statement is neutral (True from ignore), skip consistency check
            # But we treat neutral as True; it will not cause a mismatch
            if is_liar and truth:
                return False
            if not is_liar and not truth:
                return False
    return True

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.

    Args:
        heights (List[int]): A list of student heights.

    Returns:
        int: The minimum number of students that need to leave.
    """
    # Validate input
    if not isinstance(heights, list):
        raise TypeError("heights must be a list")
    for h in heights:
        if not isinstance(h, int):
            raise TypeError("all elements in heights must be integers")

    n = len(heights)
    if n <= 1:
        return 0

    # Helper function: binary search for leftmost insertion point
    def _bisect_left(a, x):
        lo, hi = 0, len(a)
        while lo < hi:
            mid = (lo + hi) // 2
            if a[mid] < x:
                lo = mid + 1
            else:
                hi = mid
        return lo

    # Compute LIS lengths ending at each index
    tails = []
    lis = [0] * n
    for i, h in enumerate(heights):
        pos = _bisect_left(tails, h)
        if pos == len(tails):
            tails.append(h)
        else:
            tails[pos] = h
        lis[i] = pos + 1

    # Compute LDS lengths starting at each index using reversed array
    rev_heights = heights[::-1]
    tails = []
    rev_lis = [0] * n
    for i, h in enumerate(rev_heights):
        pos = _bisect_left(tails, h)
        if pos == len(tails):
            tails.append(h)
        else:
            tails[pos] = h
        rev_lis[i] = pos + 1

    lds = [0] * n
    for i in range(n):
        lds[i] = rev_lis[n - 1 - i]

    # Find maximum bitonic subsequence length
    max_bitonic = 0
    for i in range(n):
        bitonic_len = lis[i] + lds[i] - 1
        if bitonic_len > max_bitonic:
            max_bitonic = bitonic_len

    return n - max_bitonic
